# Apply human-readable names from names.csv (generated by
# unpack/analysis/metag_name_functions.py) to the functions in Ghidra via PyGhidra.
import pyghidra
pyghidra.start()

import csv
import os
from ghidra.base.project import GhidraProject
from ghidra.program.model.symbol import SourceType

proj_dir = os.path.abspath('ghidra-workspace')
names_path = os.path.abspath('unpack/analysis/0286/names.csv')

print('Opening Ghidra project at:', proj_dir)
proj = GhidraProject.openProject(proj_dir, 'frontiersilicon')
try:
    prog = proj.openProgram('/', '0286_core.bin', True)
    print('Opened program (writable):', prog.getName(), 'Processor:', prog.getLanguage().getProcessor())
    
    addr_fac = prog.getAddressFactory()
    listing = prog.getListing()
    
    rows = list(csv.DictReader(open(names_path)))
    print(f'Loaded {len(rows)} names from CSV.')
    
    ren = 0
    made = 0
    skip = 0
    
    tx = prog.startTransaction("Apply function names from names.csv")
    try:
        for row in rows:
            o = row.get('offset')
            nm = row.get('name')
            if not o or not nm:
                continue
            try:
                addr_val = int(o, 16)
                a = addr_fac.getDefaultAddressSpace().getAddress(addr_val)
            except Exception:
                skip += 1
                continue
                
            fn = listing.getFunctionAt(a)
            if fn is None:
                inst = listing.getInstructionAt(a)
                if inst is None:
                    try:
                        from ghidra.app.cmd.disassemble import DisassembleCommand
                        cmd = DisassembleCommand(a, None, True)
                        cmd.applyTo(prog)
                    except:
                        pass
                try:
                    from ghidra.app.cmd.function import CreateFunctionCmd
                    cmd = CreateFunctionCmd(a)
                    cmd.applyTo(prog)
                    fn = listing.getFunctionAt(a)
                except:
                    fn = None
                if fn is not None:
                    made += 1
            
            if fn is None:
                skip += 1
                continue
                
            try:
                fn.setName(nm, SourceType.USER_DEFINED)
                ren += 1
            except Exception:
                try:
                    fn.setName(nm + '_' + o[2:], SourceType.USER_DEFINED)
                    ren += 1
                except:
                    skip += 1
                    
        print(f'METAG-APPLY named {ren} functions ({made} newly created), skipped {skip}')
        prog.endTransaction(tx, True)
    except Exception as z:
        prog.endTransaction(tx, False)
        raise z
    
    prog.release()
finally:
    proj.close()
print('Done!')
